const beforeAtmpVariableMarkup=variableMarkup;
variableMarkup=function(p){const c=db.companies.find(c=>c.id===company);return beforeAtmpVariableMarkup(p)+section('Accidents du travail et maladies professionnelles',`<p class="wide">${esc(CompanyAtmp.description(c)||'Code risque et taux AT/MP à renseigner dans la fiche entreprise.')}</p><div class="wide"><button type="button" class="btn secondary" onclick="applyCompanyAtmp()">Ajouter / actualiser la cotisation AT/MP de l’établissement</button></div><p class="wide muted">Reprend explicitement le taux de la fiche entreprise si ses dates couvrent le mois. Le montant utilise l’assiette « gross » de test ; vérifiez l’assiette applicable et les éventuels taux distincts selon les salariés. Le taux salarié de cette ligne est fixé à zéro.</p>`);};
function applyCompanyAtmp(){try{const row=CompanyAtmp.contribution(db.companies.find(c=>c.id===company),period()),form=$('#form'),labels=[...form.querySelectorAll('[name=cotLabel]')],existing=labels.filter(n=>/accidents? du travail|AT\s*\/\s*MP/i.test(n.value));if(existing.length>1)throw Error('Plusieurs lignes AT/MP existent : vérifiez leur ventilation avant de reprendre un taux unique.');if(existing.length){const node=existing[0].closest('.cot-row');if(!node)throw Error('Ouvrez les lignes de cotisations avant la reprise du taux.');for(const [name,value]of Object.entries({cotLabel:row.label,cotBaseMode:row.baseMode,cotBase:row.base,cotEmployee:'0',cotEmployer:row.employerRate})){const input=node.querySelector('[name='+name+']');if(input)input.value=value;}}else $('#cotRows').insertAdjacentHTML('beforeend',rowMarkup(row));if(form.elements.cotReviewed)form.elements.cotReviewed.value='À vérifier';refreshCalculations();toast('Taux AT/MP repris. Vérifiez les cotisations puis enregistrez la préparation.');}catch(e){toast(e.message);}}
